def norm(s):return s.replace('\u2011','-').replace('\u2013','-').replace('\u2014','-').replace('\u00ad','')
def para(s,style='BodyText'):return Paragraph(html.escape(norm(s)).replace('\n','<br/>'),st[style])
def h(s):return para(s,'Heading1')
def footer(c,d):
 c.setStrokeColor(lime);c.line(42,37,553,37);c.setFont('DejaVu',8);c.setFillColor(gray)
 c.drawString(42,23,'XIO 0.18.0  |  18.10.2026');c.drawRightString(553,23,str(d.page))
def document(path,story,title):
 SimpleDocTemplate(str(path),pagesize=(595.28,841.89),rightMargin=42,leftMargin=42,topMargin=43,bottomMargin=49,title=title,author='Ерёмин Константин Александрович').build(story,onFirstPage=footer,onLaterPages=footer)
def diagram(labels,caption):
 d=Drawing(510,115)
 n=len(labels);gap=20;w=(506-gap*(n-1))/n
 for i,label in enumerate(labels):
  x=i*(w+gap);d.add(Rect(x,36,w,65,rx=10,fillColor=ink,strokeColor=ink))
  lines=label.split('\n')
  for j,line in enumerate(lines):d.add(String(x+w/2,79-j*15,norm(line),fontName='DejaVu',fontSize=9,fillColor=lime,textAnchor='middle'))
  if i<n-1:
   xx=x+w+3;d.add(Line(xx,68,xx+12,68,strokeColor=green,strokeWidth=2));d.add(Polygon([xx+12,68,xx+7,71,xx+7,65],fillColor=green,strokeColor=green))
 return [d,para(caption,'SmallX')]
def table(rows,widths):
 t=Table([[para(str(v),'SmallX') for v in row] for row in rows],colWidths=widths,repeatRows=1,hAlign='LEFT')
 t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),lime),('VALIGN',(0,0),(-1,-1),'TOP'),('GRID',(0,0),(-1,-1),.35,colors.HexColor('#d1dacd')),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),('TOPPADDING',(0,0),(-1,-1),7)]));return t
def screenpair(names,titles):
 cells=[]
 for name,title in zip(names,titles):
  path=r/f'verification/screens-018/{name}.png'
  if not path.exists():raise RuntimeError('Missing actual screenshot '+str(path))
  image=Image(str(path));width=220;height=width*image.imageHeight/image.imageWidth
  if height>500:width*=500/height;height=500
  image.drawWidth=width;image.drawHeight=height
  cells.append([para(title,'Heading2'),image])
 return Table([[cells[0],cells[1]]],colWidths=[255,255],style=TableStyle([('VALIGN',(0,0),(-1,-1),'TOP')]))
faq=json.loads((r/'app/assets/help/faq.ru.json').read_text())
story=[Spacer(1,50),para('XIO','Title'),para('Руководство пользователя\nНастройка приложения и VPS','Title'),Spacer(1,20),para('Android 8+ • ARM64 / ARMv7 / x86_64\nВерсия 0.18.0 • Редакция 18 октября 2026 года'),Spacer(1,20)]
story+=diagram(['Устройство\nXIO','Ваш VPS\nVPN endpoint','Интернет\nСайты и сервисы'],'Схема 1. Логический путь трафика. HTTPS сайта остаётся отдельным уровнем защиты.')
story += [para('Контакт: er-ka@mail.ru. Правообладатель собственного кода: Ерёмин Константин Александрович.'),para('RIVET - экспериментальные транспорты. Приложение не гарантирует обход любых блокировок и не заявляет независимый криптографический аудит. Иллюстрации интерфейса сняты с реальной Android-сборки в эмуляторе; это не фотография Honor Magic V3.','SmallX'),PageBreak(),h('Содержание')]
chapters=['1. Требования и установка','2. Первый запуск и документы','3. Подключение по готовому профилю','4. Развёртывание собственного VPS','5. Главная и настройки соединения','6. Пользователи, администраторы и статистика','7. Раздельное туннелирование и фон','8. Настройки приложения и диагностика','9. Перенос и очистка сервера','10. Протоколы XIO и сторонние движки','11. Безопасность и устранение проблем','12. Ограничения и справочные материалы']
for c in chapters:story.append(para(c))
story += [h(chapters[0]),para('Получайте APK от доверенного издателя. Для Honor Magic V3 используется ARM64. ARMv7 предназначен для 32-битных ARM-систем; x86_64 - для совместимых Intel/AMD Android-систем и эмуляторов. В Google Play AAB позволяет доставлять подходящую архитектуру автоматически.'),para('Откройте APK и разрешите установку из выбранного источника, если Android это запросит. Для обновления используйте APK с тем же applicationId и совместимой подписью. Не удаляйте старую установку без сохранения нужных профилей: очистка данных уничтожает локальные секреты и запись ознакомления.'),para(faq[17]['a']),h(chapters[1]),para('На первом запуске прочитайте пояснение лицензии. Кнопка полного текста GPLv3 доступна до подтверждения. Установите пустую по умолчанию галочку ознакомления и нажмите «Продолжить». На следующем отдельном экране прочитайте описание работы VPN и обработки данных; подтвердите его отдельно. Пока шаги не пройдены, новое подключение через приложение или плитку не разрешается.'),para('Настройки → Лицензия и ответственность показывает локальную запись: редакцию, UTC-время по часам устройства и SHA-256 отображённого текста. Это подтверждение интерфейса, не нотариальная фиксация или электронная подпись. Для повторного ознакомления после изменения условий разработчик меняет редакцию; очистка данных сбрасывает запись.'),PageBreak(),screenpair(['licence-unchecked','vpn-disclosure'],['Лицензия: галочка не установлена','Отдельное уведомление VPN']),para('Рисунок 1. Два самостоятельных шага первого запуска. Текст можно прокручивать.','SmallX'),PageBreak(),h(chapters[2])]
for s in ['1. Нажмите «+» в нижней панели и выберите вставку ключа/конфигурации или файл.','2. Вставьте клиентский xio://, совместимый URI или текст конфигурации. Движок определяется автоматически; отдельный выбор движка не нужен.','3. Проверьте название и импортируйте. Обычный пользователь получает доступ к соединению, а не root VPS.','4. На Главной выберите сервер, нажмите «Подключиться», затем подтвердите системное разрешение Android.','5. Дождитесь проверки выбранного сайта. При неудаче проверьте и сам сайт с VPS: отсутствие ответа сайта не доказывает поломку шифрованного канала.']:
 story.append(para(s))
story += [para(faq[16]['a']),h(chapters[3]),para('Требования VPS: доступный публичный адрес, разрешённый SSH, достаточное свободное место, системный менеджер служб и TUN. Рекомендуется свежая система или резервная копия: установка добавляет пакеты и изменяет сетевые настройки. Проверки на отдельной версии ОС не подтверждают каждую доступную конфигурацию облака.'),para(faq[2]['a'])]
for s in ['1. В панели провайдера создайте VPS и узнайте IP/домен, SSH-порт, логин и способ авторизации. Настройте firewall провайдера, не закрывая SSH.','2. В XIO откройте «+» → «VPN на своём сервере». Введите адрес без схемы https://, SSH-порт и учётные данные. SSH-доступ должен позволять необходимые операции root.','3. Запустите проверку и установку. Приложение сохраняет ключ сервера после первого соединения и проверяет его при следующих подключениях. Не игнорируйте неожиданную смену ключа.','4. Дождитесь загрузки сжатого установочного комплекта, установки пакетов и запуска служб. SSH-секреты сохраняются в защищённом хранилище устройства; повторно вводить их для обычных операций не требуется.','5. После успешной установки создайте пользователя и получите его многопротокольный профиль. После добавления новых движков ранее выданные профили не получают новые секреты автоматически.','6. Вернитесь на Главную, выберите сервер и подключитесь. Не выдавайте экспорт root-конфигурации обычному пользователю вместо клиентского профиля.']:
 story.append(para(s))
story += diagram(['SSH\nПроверка ОС','Установка\nСлужбы / firewall','Пользователь\n10 профилей'],'Схема 2. Мастер развёртывания. Набор профилей зависит от успешной серверной установки.')
story += [h(chapters[4]),para('Нижняя панель содержит Главную, Настройки и «+». Между основными страницами можно проводить пальцем. На Главной расположены кнопка соединения и выбор сервера; выбор протокола вынесен в настройки.'),para(faq[3]['a']),para(faq[4]['a']),para('Настройки → Соединение: задайте контрольный HTTPS-сайт, приоритетный протокол и тайм-аут. Сохраните изменения при отключённом соединении. Приоритет не создаёт отсутствующие ключи: сторонний одиночный профиль остаётся единственным кандидатом.'),PageBreak(),screenpair(['home','add-connection'],['Главная и выбор сервера','Добавление соединения']),para('Рисунок 2. Реальные экраны XIO. Данные тестового профиля не являются общедоступным доступом к VPN.','SmallX'),PageBreak(),h(chapters[5])]
for i in [8,9,10,11]:story += [para(faq[i]['q'],'Heading2'),para(faq[i]['a'])]
story += diagram(['Владелец VPS\nСоздаёт admin','Admin\nКвота N активных','Пользователь\nКлиентский профиль'],'Схема 3. Делегирование. Отзыв освобождает место; делегированный admin не становится root.')
story += [h(chapters[6])]
for i in [12,13,14]:story += [para(faq[i]['q'],'Heading2'),para(faq[i]['a'])]
story += [para('Always-on VPN и «Блокировать соединения без VPN» включаются в системных настройках Android пользователем. Для защиты при переходах между движками это важнее простого значка «подключено». Защита каждой комбинации split-routing и kill switch требует проверки на устройстве. Не выключайте системные механизмы безопасности ради прохождения подключения.'),h(chapters[7]),para(faq[19]['a']),para('Настройки → Диагностика содержит проверки и журнал сеанса. Перед отправкой журналов убедитесь, что в них нет конфигураций, ключей и административных данных. Лицензии сторонних компонентов доступны отдельно. Ссылка «Поддержать XIO» открывает внешний сайт; это не системный экран Android.'),para('Справка и FAQ доступны без сети. В этом выпуске подробные новые юридические пояснения и FAQ представлены на русском и английском; для остальных выбранных языков эти подробные тексты используют английский вариант. Основной интерфейс сохраняет 13 языков.'),PageBreak(),screenpair(['settings','licence-record'],['Настройки и справка','Запись ознакомления на устройстве']),para('Рисунок 3. Юридическая запись видна пользователю и остаётся после обычного перезапуска.','SmallX'),PageBreak(),h(chapters[8]),para(faq[15]['a']),para('«Удалить из приложения» удаляет местную запись, а не инфраструктуру VPS. «Очистить сервер от XIO» требует доступного административного подключения, удаляет принадлежащие XIO установки и затем сервер из приложения. Если сервер недоступен, не считайте очистку выполненной. Резервные копии у провайдера и ранее разосланные клиентские файлы не исчезают от удаления записи.'),h(chapters[9])]
proto=[['Протокол','Назначение и ограничения'],['WireGuard','Компактный UDP VPN. Не является механизмом сокрытия от DPI.'],['AmneziaWG3.1','Модифицированный WireGuard с параметрами обфускации. Клиент/сервер должны совпадать по профилю.'],['RIVET/H3','HTTP/3 CONNECT-UDP/MASQUE с внутренним QUIC/TLS1.3. Экспериментальный транспорт.'],['RIVET/S1','HTTPS/WebSocket с отдельным внутренним TLS1.3. Экспериментальный TCP-транспорт.'],['Xray','Поддерживаемые VLESS REALITY/TLS, VMess AEAD и Trojan TLS. Не все варианты Xray JSON.'],['Shadowsocks','SIP002/JSON, в собственной серверной установке SS2022. Не произвольный набор плагинов.'],['OpenVPN','OpenVPN3 клиент; встроенные сертификаты/ключи, без внешних сценариев.'],['OpenVPN/Cloak','OpenVPN внутри транспорта Cloak. Два компонента, совместные настройки.'],['IKEv2/IPsec','Системный Android11+ API, доверенный CA, EAP. Ограничения split-routing.'],['Tailscale/Headscale','Mesh и выбранный exit node. Профили с control URL/CA/auth key; не произвольный OAuth вход.']]
story += [table(proto,[120,390]),Spacer(1,12),para('Наши транспорты RIVET','Heading2'),para('RIVET не заменяет TLS собственным шифром. Устройство имеет отдельные случайные секреты входа и устройства. Вход проверяет токен; шлюз проверяет доказательство знания секрета, связанное с nonce, идентификатором шлюза и TLS exporter. Привязка к конкретному защищённому сеансу препятствует повторному использованию перехваченного доказательства в другом сеансе. Шлюз доверенный: он расшифровывает туннельный трафик и хранит необходимые серверные ключи.')]
story += diagram(['HTTP/3\nCONNECT-UDP','Внутренний\nQUIC / TLS1.3','IP-пакеты\nDATAGRAM'],'Схема 4. RIVET/H3. Внешний и внутренний уровни - разные сеансы, внешний HTTP/3 не делает весь поток браузерным.')
story += diagram(['HTTPS / WSS\nALPN http/1.1','Внутренний\nTLS1.3','IP-пакеты\nПоток туннеля'],'Схема 5. RIVET/S1. TCP-транспорт может иметь задержки при потерях; сетевые отпечатки остаются измеримыми.')
story += [para('H3 требует пригодного UDP и MTU; при ограничениях пробуйте S1 или другие профили. Для существующего RIVET-сеанса есть собственное восстановление с увеличением пауз. Тайм-аут первоначальной попытки и время обнаружения обрыва - разные параметры. Перебор при первоначальном подключении не означает универсального бесшовного переключения любого уже работающего движка.'),para('Сертификаты и pins','Heading2'),para('Для HTTPS-проверок старых Android добавлены четыре действующих публичных корневых сертификата GTS/SSL.com из проверенного набора Mozilla/curl. Это не обновляет браузер или хранилище сертификатов всей ОС. Самоподписанные чужие сертификаты по-прежнему отклоняются.'),para('Проверка TLS и pinning не отключаются. Внешний и внутренний сертификаты имеют разные роли. При смене сертификата обновите доверенную конфигурацию правильным способом. Автоматическое продление внешнего сертификата не заявляется: следите за сроком его действия. «Allow insecure» не является исправлением недействительного сертификата.'),h(chapters[10]),table([['Симптом','Что проверить'],['Нет ярлыка','Откройте список приложений и поиск XIO. Проверьте выбранный launcher и обновление с той же подписью; некоторые лаунчеры кешируют alias.'],['Все протоколы не проходят','Сайт проверки; доступность VPS; firewall провайдера; свободные порты; время устройства и сертификаты.'],['Работает Wi-Fi, не работает мобильная сеть','UDP/MTU, IPv6, ограничения оператора. Сравните H3/S1 и другой контрольный HTTPS-адрес.'],['Не создаётся пользователь','SSH-доступ, исправность установки, права admin и лимит действующих пользователей.'],['Плитка не подключает','Первичный запуск, подтверждения, системное разрешение и сохранённый профиль.'],['Трафик не обновился','Снимок читается раз за процесс при доступном SSH; перезапуск Activity не всегда создаёт новый процесс.'],['Ошибка импорта','Поддерживаемый формат, размер, inline-ключи и CA; скрипты и небезопасные настройки отклоняются.']],[140,370]),PageBreak(),h(chapters[11]),para('Проверки в эмуляторе и на VPS не заменяют испытания на физическом Honor, разных операторах и длительную нагрузку. Android8+ и три ABI расширяют совместимость, но не означают поддержку всех устройств, TV, часов и автомобильных систем. Полный перенос новых движков в Windows/Ubuntu не заявляется.'),para('Проверка выпуска 0.18.0','Heading2'),table([['Контур','Что проверялось'],['Android 15, x86_64 + Debian VPS','Реальные подключения движков и HTTPS-проверка, переключение после отказа, фоновая служба и плитка.'],['Android 8, x86_64','Установка, первый запуск, локальная запись и RIVET/H3 с HTTPS 200 после добавления публичных корней.'],['Пользователи на VPS','Отдельная ограниченная SSH-авторизация, квота активных пользователей, освобождение места после отзыва, запрет создания администраторов делегатом.'],['Автоматизированные проверки','Flutter, серверные тесты, Go race/vet, отрицательная TLS-проверка и ограничение бюджета повторов.'],['Остаётся проверить','Физические устройства, длительную нагрузку, разные сети и страны; DPI-неразличимость и независимый аудит не подтверждены.']],[145,365]),para('Технические материалы в исходниках: RIVET-IMPLEMENTATION-0.2.ru.md; RIVET-1-ARCHITECTURE.ru.md; legal/SOURCE-BUILD.ru.md; verification/VERIFICATION-0.18.0.ru.md. Источники стандартов: RFC9297, RFC9298, RFC9221; Go crypto/tls; документация Android VpnService. Экспериментальную архитектуру нужно отличать от результатов реализованной версии.')]
